const groups=[{title:'The place is the anchor.',scope:'REQUIRED FOR IMPORT',links:[['poh','georeference_poh','georeference_poh_ID · one coordinate per place'],['poh','pohtype','pohType_ID → identifier · 21 type rows'],['poh','contributor','contributor_ID · link only; personal fields omitted'],['payload_poh','poh','poh_ID · DE / GB translations'],['sources_poh','poh','poi_id · citations'],['sources_poh','source_type','source_type · inferred by name'],['poh2keyword','poh + keywords','poh_ID / keyword · tagging join']],note:'Documented no-orphan checks cover the relations of poh, payload_poh, sources_poh and poh2keyword. This page has not repeated those checks.'},{title:'A small temporal branch.',scope:'DOCUMENTED LEGACY RELATIONSHIPS',links:[['timelinecluster','poh','poh_ID'],['timeline','timelinecluster','timelinecluster_ID'],['timesegment','timeline','timeline_ID; timesegment_id self-reference'],['payload_tc / payload_tl / payload_ts','temporal parent','timelinecluster_id / timeline_id / timesegment_id'],['sources_tl / sources_ts','timeline / timesegment','poi_id · both source tables empty']],note:'Timeline tables have one row each, for one place. timelinecluster links were documented as checked; the other links are inferred by name.'},{title:'Lookup-led evaluation.',scope:'OUTSIDE IMPORT SCOPE',links:[['evaluation','poh + evaluation_Type','poh_id / evaluations_Type_ID'],['evaluations','evaluation_Type','evaluation_type_id · 30 evaluation rows documented'],['poh_evalAccess','poh + evalAccess','poh_ID / evalAccess_ID']],note:'Relations are inferred by name. Unreferenced five-row lookups: evalInfoQuality, evalInfoQuantity, evalPosition, evalProcessing, evalSphere, evalVisibility and evalAvarcInfo; each has ID, Tag and Description.'},{title:'Collections and their items.',scope:'OUTSIDE IMPORT SCOPE',links:[['collection','contributor','contributor_id'],['collectionItem','collection + poh','collection_ID / poh_id; includes contributor_poh_id and index']],note:'All links in this group are inferred by name only. No collection data is imported by this demonstration.'},{title:'Sensitive edges, limited exposure.',scope:'OUTSIDE IMPORT SCOPE',links:[['poh2author','poh + author','poh_id / author_id · personal columns omitted'],['poh2person','poh + person + person_role','poh_id / person_id / person_role · empty join and person'],['address','contributor','contributor_ID · empty personal table'],['poh2attribute','poh + attribute','poh_id / attribute_id'],['attribute','attributeTypes','type · name-based link; subordinateTo also present']],note:'author, contributor, address and person are personal-data tables. Contents are omitted. attributes is an additional unlinked attribute/type lookup.'},{title:'Peripheral and unlinked tables.',scope:'REFERENCE ONLY',links:[['user','personal / credential table','username and password content is never loaded'],['mapzero','standalone map points','id, name, latitude, longitude'],['sphere','standalone reference','ID, name, abstract'],['iso-3166-1','country lookup','Alpha2, Alpha3, englishName · 249 rows'],['BEG','empty unreferenced table','ID only']],note:'No relationship is asserted for these tables. The importer does not read user credentials.'}];const $=s=>document.querySelector(s);function group(i){const g=groups[i];$('#groupTitle').textContent=g.title;$('#scope').textContent=g.scope;$('#map').innerHTML=g.links.map(l=>'<div class="relation"><span class="table">'+l[0]+'</span><span>→</span><span class="table">'+l[1]+'</span></div><p class="rel-note">'+l[2]+'</p>').join('');$('#confidence').textContent=g.note;document.querySelectorAll('[data-group]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.group===String(i)))}document.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>group(b.dataset.group));$('#coordinateForm').onsubmit=e=>{e.preventDefault();const a=$('#lat').value.trim(),b=$('#lng').value.trim(),decimal=/^[+-]?(?:\d+(?:\.\d+)?|\.\d+)$/;$('#coordinateResult').textContent=!decimal.test(a)||!decimal.test(b)?'Needs review: values must be plain decimal text. Ambiguous formats are not auto-converted.':Math.abs(+a)>90||Math.abs(+b)>180?'Out of range: latitude ±90, longitude ±180.':'Plain decimal pair within range. SRID 4326. Syntax check only; provenance is not verified.'};function language(){$('#languageResult').textContent={DE:'DE → German. Suggested application language: de.',GB:'GB → English. Suggested application language: en.',EN:'EN is not the documented legacy English code. Review this value; legacy English is GB.'}[$('#language').value]}$('#language').onchange=language;group(0);language();